async function watchSafetyHash(durationMs=45000) {
 const state=load("replyHashTwoTabWatchState");
 if(state.halt_requested||state.hash){text({status:state.status,hash:state.hash});return;}
 const capture=async(label)=>{
  const r=await tools.mcp__node_repl__js({code:"console.log(JSON.stringify({primary:await replySafetyCapture('primary',"+JSON.stringify(label)+"),secondary:await replySafetyCapture('secondary',"+JSON.stringify(label)+")}));",title:"Observe the original wallet request in both tabs",timeout_ms:10000});
  state.raw_calls.push(r);store("replyHashTwoTabWatchState",state);
  if(r.isError)throw Error(JSON.stringify(r));let pair;
  for(const c of r.content??[])if(c.type==="text"){try{pair=JSON.parse(c.text);}catch{}}
  if(!pair)throw Error("Missing DOM observations");state.observations.push(pair);store("replyHashTwoTabWatchState",state);return pair;
 };
 state.active=true;state.status="CAPTURING";const started=Date.now();store("replyHashTwoTabWatchState",state);
 let pair=await capture("capture_cycle_started");
 text({observer:"ACTIVE",primary_waiting:pair.primary.visible.waiting_wallet,secondary_uncertain:pair.secondary.visible.uncertain,hash:pair.primary.visible.hash||pair.secondary.visible.hash});await yield_control();
 while(Date.now()-started<durationMs){
  try {
   pair=await capture("watch_original_request_without_resending");
   const hashes=[...new Set([pair.primary.visible.hash,pair.secondary.visible.hash].filter(Boolean))];
   if(hashes.length>1)throw Error("Tabs show conflicting recovery hashes");
   if(hashes.length){
    if(state.prohibited_hashes.includes(hashes[0]))throw Error("A completed old hash cannot be used as the new request");
    state.hash=hashes[0];state.status="FRESH_HASH_OBSERVED";state.active=false;state.hash_observation=pair;store("replyHashTwoTabWatchState",state);text({status:state.status,hash:state.hash,primary:pair.primary.visible,secondary:pair.secondary.visible});return;
   }
   if(!pair.primary.visible.waiting_wallet&&!pair.secondary.visible.waiting_wallet){
    state.status=(pair.primary.visible.uncertain||pair.secondary.visible.uncertain)?"UNKNOWN_OUTCOME_INSPECT_WITHOUT_RESENDING":"REQUEST_ENDED_WITHOUT_HASH_INSPECT";state.active=false;state.halt_requested=true;store("replyHashTwoTabWatchState",state);text({status:state.status});return;
   }
  }catch(error){state.errors.push(String(error));state.status="NEEDS_ATTENTION";state.active=false;state.halt_requested=true;store("replyHashTwoTabWatchState",state);text({status:state.status,error:String(error)});return;}
  await new Promise(resolve=>setTimeout(resolve,2500));
 }
 state.active=false;state.status="CYCLE_COMPLETE_CAN_CONTINUE";store("replyHashTwoTabWatchState",state);text({status:state.status,hash:state.hash,observations:state.observations.length});
}
